target_restaurant as (
  select id
  from public.restaurants
  where code = '02014'
),
active_products as (
  select
    p.id,
    p.restaurant_id,
    p.iiko_code
  from public.order_products p
  join target_restaurant r
    on r.id = p.restaurant_id
  where p.is_active is true
),
unique_product_codes as (
  select p.iiko_code
  from active_products p
  join source s
    on s.iiko_code = p.iiko_code
  group by p.iiko_code
  having count(*) = 1
),
source_products as (
  select
    s.*,
    p.id as product_id,
    p.restaurant_id
  from source s
  left join unique_product_codes u
    on u.iiko_code = s.iiko_code
  left join active_products p
    on p.iiko_code = s.iiko_code
   and p.iiko_code = u.iiko_code
),
written as (
  insert into public.product_weekly_usage (
    restaurant_id,
    product_id,
    monday,
    tuesday,
    wednesday,
    thursday,
    friday,
    saturday,
    sunday,
    review_interval_days,
    last_reviewed_at
  )
  select
    s.restaurant_id,
    s.product_id,
    s.monday,
    s.tuesday,
    s.wednesday,
    s.thursday,
    s.friday,
    s.saturday,
    s.sunday,
    14,
    current_date
  from source_products s
  where s.product_id is not null
  on conflict (restaurant_id, product_id) do update
    set monday = excluded.monday,
        tuesday = excluded.tuesday,
        wednesday = excluded.wednesday,
        thursday = excluded.thursday,
        friday = excluded.friday,
        saturday = excluded.saturday,
        sunday = excluded.sunday,
        review_interval_days = excluded.review_interval_days,
        last_reviewed_at = excluded.last_reviewed_at
  returning product_id
),
skipped as (
  select iiko_code
  from source_products
  where product_id is null
),
duplicate_codes as (
  select s.iiko_code
  from source s
  join active_products p
    on p.iiko_code = s.iiko_code
  group by s.iiko_code
  having count(*) > 1
)
select
  (select count(*) from target_restaurant) as matching_restaurants,
  (select count(*) from source) as source_products,
  (select count(*) from written) as upserted_products,
  (select count(*) from skipped) as skipped_products,
  coalesce(
    (select string_agg(iiko_code, ', ' order by iiko_code) from skipped),
    'none'
  ) as skipped_iiko_codes,
  coalesce(
    (select string_agg(iiko_code, ', ' order by iiko_code) from duplicate_codes),
    'none'
  ) as duplicate_active_iiko_codes;
